import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])

    if k <= n + 1:
        print((k - 1) // 2)
        return

    if k >= n * 2:
        print(0)
        return

    print(n - k // 2)

if __name__ == "__main__":
    main()

