import java.io.BufferedInputStream
import java.util.*

fun main(args: Array<String>) {
    val scanner = Scanner(BufferedInputStream(System.`in`))

    val n = scanner.nextLong()
    val k = scanner.nextLong()

    if (k <= n + 1) {
        println((k - 1) / 2)
        return
    }

    if (k >= n * 2) {
        println(0)
        return
    }

    if (k % 2 == 1L) {
        println(n - k / 2)
        return
    } else {
        println(n - k / 2)
        return
    }
}
